137	    @Transactional
138	    public List<Period> rollover(String sheetId, String user, int year) {
139	        // Lock the sheet so no claim or period changes while the year is carried over.
140	        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
141	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new PeriodNotPermittedException();
142	        YearMonth start = YearMonth.of(year, settings.fiscalStartMonth(sheetId));
143	        LocalDate oldFirst = start.atDay(1);
144	        LocalDate oldLast = start.plusMonths(11).atEndOfMonth();
145	        List<Period> old = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
146	                .filter(p -> !p.getFromDate().isBefore(oldFirst) && !p.getFromDate().isAfter(oldLast))
147	                .toList();
148	        if (old.isEmpty()) throw new RolloverRefusedException();
149	        Period last = old.stream().max(Comparator.comparing(Period::getToDate)).orElseThrow();
150	        LocalDate end = last.getToDate();
151	        List<Person> sheetPeople = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
152	        Map<Long, Person> byId = sheetPeople.stream().collect(Collectors.toMap(Person::getId, Function.identity()));
153	        Map<Long, BigDecimal> open = new LinkedHashMap<>();
154	        for (Person person : sheetPeople) open.put(person.getId(), BigDecimal.ZERO.setScale(2));
155	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
156	            Person person = byId.get(claim.getPersonId());
157	            if (person == null || old.stream().noneMatch(p -> p.contains(claim.getDueBy()))) continue;
158	            ClaimStatus status = claim.statusAt(end);
159	            if (status == null || !status.isOpen() || !person.countsAt(claim, end, today)) continue;
160	            BigDecimal figure = claimService.chargedFigureOf(sheetId, person, claim);
161	            if (figure != null) open.merge(person.getId(), figure, BigDecimal::add);
162	        }
163	        List<Period> made = generateFiscalYear(sheetId, user, year + 1);
164	        LocalDate newFirst = start.plusMonths(12).atDay(1);
165	        LocalDate newLast = start.plusMonths(23).atEndOfMonth();
166	        Period first = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
167	                .filter(p -> !p.getFromDate().isBefore(newFirst) && !p.getFromDate().isAfter(newLast))
168	                .findFirst().orElse(null);
169	        Map<Long, BigDecimal> added = new LinkedHashMap<>();
170	        boolean carried = rollovers.findById(sheetId).filter(r -> r.getFiscalYear() == year).isPresent();
171	        if (first != null && !carried) {
172	            for (Person person : sheetPeople) {
173	                BigDecimal amount = open.get(person.getId());
174	                if (amount.signum() <= 0) continue;
175	                first.addOpening(person.getId(), amount);
176	                added.put(person.getId(), amount);
177	                audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user.strip()
178	                        + " name=" + person.getName() + " period=" + first.getName()
179	                        + " amount=" + amount.setScale(2).toPlainString());
180	            }
181	            periods.saveAndFlush(first);
182	        }
183	        rollovers.findById(sheetId).ifPresent(before -> {
184	            rollovers.delete(before);
185	            rollovers.flush();
186	        });
187	        rollovers.saveAndFlush(new Rollover(sheetId, year, user.strip(), today, first == null ? null : first.getId(),
188	                made.stream().map(Period::getId).toList(), added));
189	        audit.recordOnCommit("ROLLOVER sheet=" + sheetId + " by=" + user.strip()
190	                + " fy=FY" + year + " periods=" + made.size());
191	        return made;
192	    }
193	
194	    /**
195	     * The steward who made the sheet's last rollover undoes it on the same sheet-today: the periods it generated
196	     * are removed and the opening balances it added are taken back. Refused when there is none to undo, on a
197	     * later day, for anyone else, or when a claim (whatever its status) is dated or due in a period it generated.
198	     */
199	    @Transactional
200	    public void undoRollover(String sheetId, String user) {
201	        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
202	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new PeriodNotPermittedException();
203	        Rollover last = rollovers.findById(sheetId).orElseThrow(RolloverUndoRefusedException::new);
204	        if (!last.getMadeBy().equals(user.strip()) || !last.getMadeOn().equals(today)) {
205	            throw new RolloverUndoRefusedException();
206	        }
207	        List<Period> generated = periods.findAllById(last.getPeriodIds()).stream()
208	                .filter(p -> p.getSheetId().equals(sheetId))
209	                .toList();
210	        boolean claimed = claims.findBySheetIdOrderByIdDesc(sheetId).stream().anyMatch(c -> generated.stream()
211	                .anyMatch(p -> (c.getDate() != null && p.contains(c.getDate()))
212	                        || (c.getDueBy() != null && p.contains(c.getDueBy()))));
213	        if (claimed) throw new RolloverUndoRefusedException();
214	        Long openingId = last.getOpeningPeriodId();
215	        if (openingId != null && generated.stream().noneMatch(p -> p.getId().equals(openingId))) {
216	            periods.findByIdAndSheetId(openingId, sheetId).ifPresent(period -> {
217	                last.getOpenings().forEach(period::takeOpening);
218	                periods.saveAndFlush(period);
219	            });
220	        }
221	        periods.deleteAll(generated);
222	        periods.flush();
223	        rollovers.delete(last);
224	        rollovers.flush();
225	        audit.recordOnCommit("ROLLOVER_UNDONE sheet=" + sheetId + " by=" + user.strip()
226	                + " fy=FY" + last.getFiscalYear());
227	    }
228	
229	    /**
230	     * Make the four calendar quarters of the year as periods named &lt;yyyy&gt;-Q1 to &lt;yyyy&gt;-Q4, each from
231	     * the first day of its first month to the last day of its third, as the period form would add it. A
232	     * quarter whose name is already a period, or whose days overlap one on the sheet, is left out; the
233	     * others are still made.
234	     */
235	    @Transactional
236	    public List<Period> generateQuarters(String sheetId, String user, int year) {
237	        // Lock the sheet so two users adding periods at once cannot overlap or share a name.
238	        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
239	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
240	        List<Period> made = new ArrayList<>();
241	        for (int quarter = 1; quarter <= 4; quarter++) {
242	            String name = year + "-Q" + quarter;
243	            LocalDate first = YearMonth.of(year, quarter * 3 - 2).atDay(1);
244	            LocalDate last = YearMonth.of(year, quarter * 3).atEndOfMonth();
245	            if (existing.stream().anyMatch(p -> p.getName().equals(name) || p.overlaps(first, last))) continue;
246	            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
247	            existing.add(saved);
248	            made.add(saved);
249	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user.strip()
250	                    + " period=" + saved.getName() + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
251	        }
252	        return made;
253	    }
254	
255	    @Transactional
256	    public Period close(String sheetId, String user, Long id) {
257	        // Lock the sheet so no claim in the period changes while its due-total is fixed.
258	        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
259	        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
260	        if (!settings.mayDo(sheetId, user, "close")) throw new PeriodNotPermittedException();
261	        if (period.isClosed()) throw new PeriodClosedException();
262	        return fix(sheetId, user, period, today, false, false);
263	    }
264	
265	    @Transactional
266	    public Period softClose(String sheetId, String user, Long id) {
267	        // Lock the sheet so no claim in the period changes while its due-total is fixed.
268	        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
269	        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
270	        if (!settings.mayDo(sheetId, user, "close")) throw new PeriodNotPermittedException();
271	        if (period.isClosed() || period.isSoftClosed()) throw new PeriodClosedException();
272	        return fix(sheetId, user, period, today, false, true);
273	    }
274	
275	    /**
276	     * Close, as a close by hand would, every open period (not a soft-closed one) whose to-date plus the grace days is before the
277	     * sheet's today, in order of their to-dates, each audited with auto=yes. The caller holds the sheet's
278	     * lock, with its new today already set.
279	     */
280	    @Transactional
281	    public void autoClose(String sheetId, String user, LocalDate today, int graceDays) {
282	        List<Period> due = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
283	                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getToDate().plusDays(graceDays).isBefore(today))
284	                .sorted(Comparator.comparing(Period::getToDate))
285	                .toList();
286	        for (Period period : due) fix(sheetId, user, period, today, true, false);
287	    }
288	
289	    /** Close or soft-close the period, fixing each person's due-total for it and its own, and audit it. */
290	    private Period fix(String sheetId, String user, Period period, LocalDate today, boolean auto, boolean soft) {
291	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
292	                .collect(Collectors.toMap(Person::getId, Function.identity()));
293	        // Every person on the sheet gets a figure, 0.00 when none of their claims falls in it.
294	        Map<Long, BigDecimal> personDues = new LinkedHashMap<>();
295	        for (Long personId : byId.keySet()) personDues.put(personId, BigDecimal.ZERO.setScale(2));
296	        Map<Long, BigDecimal> personCarried = new LinkedHashMap<>(personDues);
297	        // their opening balances for it are part of what they carry into it
298	        period.getOpenings().forEach((personId, amount) -> {
299	            if (personCarried.containsKey(personId)) personCarried.merge(personId, amount, BigDecimal::add);
300	        });
301	        List<Period> all = periods.findBySheetIdOrderByFromDateAsc(sheetId);
302	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
303	            Person person = byId.get(claim.getPersonId());
304	            if (person == null || !person.countsAt(claim, period.getToDate(), today)) continue;
305	            if (period.contains(claim.getDueBy())) {
306	                BigDecimal figure = claimService.chargedFigureOf(sheetId, person, claim);
307	                if (figure != null) personDues.merge(person.getId(), figure, BigDecimal::add);
308	            } else if (carriedInto(period, claim, all)) {
309	                BigDecimal figure = claimService.chargedFigureOf(sheetId, person, claim);
310	                if (figure != null) personCarried.merge(person.getId(), figure, BigDecimal::add);
311	            }
312	        }
313	        // every pool member's cut as it stands now
314	        List<PoolCutLine> cuts = new ArrayList<>();
315	        for (PoolService.PoolLine pool : pools.pools(sheetId)) {
316	            for (PoolService.Member m : pool.members()) {
317	                cuts.add(new PoolCutLine(pool.id(), pool.crewId(), m.personId(), m.poolId(), m.cut()));
318	            }
319	        }
320	        period.fixPoolCuts(cuts);
321	        if (soft) period.softClose(personDues, personCarried);
322	        else period.close(personDues, personCarried);
323	        Period saved = periods.saveAndFlush(period);
324	        audit.recordOnCommit((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + user.strip()
325	                + " period=" + saved.getName() + " total=" + saved.getClosedDueTotal().setScale(2).toPlainString()
326	                + (auto ? " auto=yes" : ""));
327	        return saved;
328	    }
329	
330	    /**
331	     * Whether the claim is carried into the period: due in a period ending before it starts, and still
332	     * open (OPEN or PENDING) at the end of its last day, by the status log.
333	     */
334	    private static boolean carriedInto(Period period, Claim claim, List<Period> all) {
335	        Period own = all.stream().filter(p -> p.contains(claim.getDueBy())).findFirst().orElse(null);
336	        if (own == null || !own.getToDate().isBefore(period.getFromDate())) return false;
337	        ClaimStatus status = claim.statusAt(period.getToDate());
338	        return status != null && status.isOpen();
339	    }
340	
341	    @Transactional
342	    public Period reopen(String sheetId, String user, Long id) {
343	        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
344	        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
345	        if (!settings.mayDo(sheetId, user, "reopen")) throw new PeriodNotPermittedException();
346	        if (!period.isClosed() && !period.isSoftClosed()) throw new PeriodOpenException();
347	        if (period.isLocked()) throw new PeriodLockedException();
348	        period.reopen();
349	        Period saved = periods.saveAndFlush(period);
350	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user.strip()
351	                + " period=" + saved.getName());
352	        return saved;
353	    }
354	
355	    /** A steward locks the period, or unlocks it; locking a locked one or unlocking an unlocked one is refused. */
356	    @Transactional
357	    public Period lock(String sheetId, String user, Long id, boolean lock) {
358	        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
359	        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
360	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new PeriodNotPermittedException();
361	        if (lock && period.isLocked()) throw new PeriodLockedException();
362	        if (!lock && !period.isLocked()) throw new PeriodNotLockedException();
363	        period.setLocked(lock);
364	        Period saved = periods.saveAndFlush(period);
365	        audit.recordOnCommit((lock ? "PERIOD_LOCKED" : "PERIOD_UNLOCKED") + " sheet=" + sheetId + " by=" + user.strip()
366	                + " period=" + saved.getName());
367	        return saved;
368	    }
369	}
